#include <vector>

using namespace std;

class Solution {
public:
    bool canBeIncreasing(vector<int>& nums) {
        int cnt = 0;
        int n = nums.size();
        for (int i = 1; i < n; ++i) {
            if (nums[i] <= nums[i - 1]) {
                cnt++;
                if (cnt > 1) return false;
                if (i > 1 && nums[i] <= nums[i - 2]) {
                    nums[i] = nums[i - 1];
                }
            }
        }
        return true;
    }
};

class Solution {
    public boolean canBeIncreasing(int[] nums) {
        int cnt = 0;
        int n = nums.length;
        for (int i = 1; i < n; ++i) {
            if (nums[i] <= nums[i - 1]) {
                cnt++;
                if (cnt > 1) return false;
                if (i > 1 && nums[i] <= nums[i - 2]) {
                    nums[i] = nums[i - 1];
                }
            }
        }
        return true;
    }
}

