var canBeIncreasing = function(nums) {
    const arr = [...nums];
    let cnt = 0;
    for (let i = 1; i < arr.length; ++i) {
        if (arr[i] <= arr[i - 1]) {
            cnt++;
            if (cnt > 1) return false;
            if (i > 1 && arr[i] <= arr[i - 2]) {
                arr[i] = arr[i - 1];
            }
        }
    }
    return true;
};
